<template>
  <div class="page-container rule-execution-logs-page">
    <!-- Intro + doc type. Same header block as the rule-builder lists. -->
    <div class="page-head">
      <div class="page-intro">
        <h3 class="fb-title page-intro__title">
          {{ $t('rule_execution_logs') }}
        </h3>
        <p class="page-intro__subtitle page-intro__subtitle--md">
          {{ $t('rule_execution_logs_description') }}
        </p>
      </div>

      <div v-if="doc_type_key" class="page-doctype">
        <Icon icon="mdi:file-document-outline" class="page-doctype__icon" />
        <span class="page-doctype__label">{{ $t('document_type') }}</span>
        <span class="page-doctype__value" data-test="doc-type">{{
          doc_type_key
        }}</span>
      </div>
    </div>

    <!-- Query bar. Every control is an optional filter: the page opens on the
         whole trail for the selected rule family and narrows from there. -->
    <q-card flat bordered class="rel-query mb-4">
      <q-card-section class="rel-query__body p-4">
        <div class="rel-selector-row flex flex-wrap items-end gap-4">
          <div>
            <label class="rb-label">
              {{ $t('find_by') }}
              <span class="rel-required">{{ $t('required') }}</span>
            </label>
            <q-btn-toggle
              v-model="mode"
              no-caps
              unelevated
              toggle-color="primary"
              class="list-filter-toggle"
              data-test="rel-mode"
              :options="modeOptions"
            />
          </div>

          <!-- One input, relabelled to whichever parameter the mode selects, so
               the control and the query string read the same. -->
          <div class="rel-field rel-field--wide">
            <label class="rb-label">{{ mode }}</label>
            <q-input
              outlined
              dense
              clearable
              debounce="400"
              class="rb-mono"
              v-model="selector"
              data-test="rel-selector"
              :placeholder="selectorPlaceholder"
            />
          </div>

          <!-- A document's run leaves entries from all three families behind,
               so filtering by doc_id has to say which kind it wants. -->
          <div v-if="mode === 'doc_id'" class="rel-field">
            <label class="rb-label">
              {{ $t('rule_type') }}
              <span class="rel-required">{{ $t('required') }}</span>
            </label>
            <q-select
              outlined
              dense
              emit-value
              map-options
              v-model="ruleTypeRequired"
              data-test="rel-rule-type-required"
              :options="ruleTypeRequiredOptions"
            />
          </div>
        </div>

        <!-- The six filters the endpoint narrows on. doc_type is fixed by the
             route this page is reached from, so it is shown for completeness
             but not editable — changing it here would contradict the heading. -->
        <div class="rel-filters">
          <div v-if="mode !== 'doc_id'">
            <label class="rb-label">{{ $t('rule_type') }}</label>
            <q-select
              outlined
              dense
              emit-value
              map-options
              v-model="ruleType"
              data-test="rel-rule-type"
              :options="ruleTypeFilterOptions"
            />
          </div>
          <div>
            <label class="rb-label">{{ $t('outcome') }}</label>
            <q-select
              outlined
              dense
              emit-value
              map-options
              v-model="outcome"
              data-test="rel-outcome"
              :options="outcomeOptions"
            />
          </div>
          <div>
            <label class="rb-label">{{ $t('executed') }}</label>
            <q-select
              outlined
              dense
              emit-value
              map-options
              v-model="executed"
              data-test="rel-executed"
              :options="executedOptions"
            />
          </div>
          <div>
            <label class="rb-label">{{ $t('document_type') }}</label>
            <q-input
              outlined
              dense
              readonly
              class="rel-field--locked"
              :model-value="doc_type_key"
              data-test="rel-doc-type"
            >
              <template v-slot:append>
                <Icon icon="mdi:lock-outline" class="size-3.5 opacity-50" />
              </template>
            </q-input>
          </div>
          <div>
            <label class="rb-label">{{ $t('from_date') }}</label>
            <q-input
              outlined
              dense
              type="date"
              v-model="fromDate"
              data-test="rel-from"
            />
          </div>
          <div>
            <label class="rb-label">{{ $t('to_date') }}</label>
            <q-input
              outlined
              dense
              type="date"
              v-model="toDate"
              data-test="rel-to"
            />
          </div>
        </div>
      </q-card-section>

      <!-- The call the filters above add up to, so the trail on screen can be
           traced back to a request. Mirrors what runQuery() actually sends. -->
      <div class="rel-request" data-test="rel-request">
        <span class="rel-request__verb">GET</span>
        <code class="rel-request__url"
          ><span
            v-for="(token, index) in requestTokens"
            :key="index"
            :class="token.key ? 'rel-request__key' : ''"
            >{{ token.text }}</span
          ></code
        >
      </div>
    </q-card>

    <!-- The endpoint's own contract, answered before the call is made: an
         invalid query is refused here with the status it would have come back
         with, rather than sent and shown as a failure. -->
    <div
      v-if="queryError"
      class="rel-notice"
      role="status"
      data-test="rel-notice"
    >
      <span class="rel-notice__status">{{ queryError.code }}</span>
      <div>
        <p class="rel-notice__msg">{{ queryError.message }}</p>
        <p class="rel-notice__hint">{{ queryError.hint }}</p>
      </div>
    </div>

    <!-- How many entries the active filters match, from the one request the
         table already makes. Per-outcome counts would each cost their own
         request, so they are read by setting the filter instead. -->
    <div class="rel-stats" data-test="rel-stats">
      <span class="rel-stat">
        <b>{{ total }}</b
        >{{ $t('log_entries') }}
      </span>
    </div>

    <DocBitsTable
      :rows="rows"
      :columns="columns"
      row-key="id"
      table-id="rule_execution_logs_table"
      :loading="loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: false,
        pagination: true,
        columnReorder: false,
      }"
      :pagination="paginationState"
      :rows-per-page-options="[10, 25, 50]"
      no-data-label="no_rule_execution_logs"
      flat-style
      data-test="rule-execution-logs-table"
      @update:pagination="handlePaginationChange"
      @row-click="openDetail"
    >
      <template #body-cell-created_on="{ row }">
        <span class="rel-cell-time">{{ formatTimestamp(row.created_on) }}</span>
      </template>

      <template #body-cell-outcome="{ row }">
        <span class="rel-pill" :class="outcomeClass(row.outcome)">
          {{ outcomeLabel(row.outcome) }}
        </span>
      </template>

      <template #body-cell-rule_key="{ row }">
        <div class="rel-rule-key">{{ row.rule_key }}</div>
        <span class="rel-family">{{ ruleTypeLabel(row.rule_type) }}</span>
      </template>

      <template #body-cell-scope="{ row }">
        <span class="rel-mono">{{ scopeLabel(row) }}</span>
      </template>

      <template #body-cell-doc_id="{ row }">
        <div class="rel-mono">{{ row.doc_id || '—' }}</div>
        <div v-if="row.doc_type" class="rel-meta">{{ row.doc_type }}</div>
      </template>

      <template #body-cell-row_index="{ row }">
        <span class="rel-mono">{{
          row.row_index === null ? '—' : row.row_index
        }}</span>
      </template>

      <template #body-cell-severity="{ row }">
        <span v-if="row.severity" :class="severityClass(row.severity)">
          {{ severityLabel(row.severity) }}
        </span>
        <span v-else class="rel-mono">—</span>
      </template>
    </DocBitsTable>

    <!-- Detail panel — the full entry plus the engine's raw `details` payload,
         whose shape depends on the rule family. -->
    <q-dialog v-model="detailOpen" position="right" full-height>
      <q-card class="rel-detail">
        <q-toolbar class="secondary-toolbar">
          <q-toolbar-title class="text-white">
            <span class="text-sm font-semibold">{{
              detailRow ? detailRow.rule_key : ''
            }}</span>
          </q-toolbar-title>
          <q-btn
            flat
            round
            dense
            class="text-white"
            data-test="rel-detail-close"
            v-close-popup
          >
            <Icon icon="mdi:close" class="size-4" />
          </q-btn>
        </q-toolbar>

        <q-card-section v-if="detailRow" class="rel-detail__body">
          <div class="rel-detail__section">
            <h4 class="rb-label">{{ $t('log_entry') }}</h4>
            <dl class="rel-kv">
              <template v-for="field in detailFields" :key="field.key">
                <dt>{{ field.key }}</dt>
                <dd>{{ field.value }}</dd>
              </template>
            </dl>
          </div>

          <div class="rel-detail__section">
            <h4 class="rb-label">{{ $t('log_details') }}</h4>
            <pre class="rel-json" data-test="rel-detail-json">{{
              detailsJson
            }}</pre>
          </div>
        </q-card-section>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { useFormattedTimestamp } from 'src/boot/timeago';
import { ruleExecutionLogsApiService } from 'src/services';
import type {
  RuleExecutionLog,
  RuleExecutionLogQuery,
  RuleFamily,
  RuleOutcome,
} from 'src/services/settings/RuleExecutionLogsApiService';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type {
  PaginationChangePayload,
  UnifiedTableColumn,
} from 'src/components/Table/types/table/unified-table';

/** Which parameter the selector input feeds. These are the API's own parameter
 *  names, and the label above the input shows them verbatim. */
type SelectorMode = 'rule_key' | 'rule_id' | 'doc_id';

/** A query the endpoint would refuse, answered before it is sent. */
interface QueryError {
  code: number;
  message: string;
  hint: string;
}

// Outcomes, in the order the API documents them: validation, transformation,
// then layout selection. `skipped` is shared by the first two.
const OUTCOMES: RuleOutcome[] = [
  'passed',
  'failed',
  'skipped',
  'applied',
  'no_change',
  'matched',
  'not_matched',
];

export default defineComponent({
  name: 'RuleExecutionLogsList',
  components: { DocBitsTable, Icon },
  data() {
    return {
      doc_type_key: '',
      // Which parameter the selector input feeds. One of the three is required:
      // the table holds one row per evaluation per document, so there is no
      // org-wide listing to page through.
      mode: 'rule_key' as SelectorMode,
      selector: '',
      // The family filter. Free to be "Any" — except in doc_id mode, where the
      // endpoint requires one and `ruleTypeRequired` supplies it instead.
      ruleType: '' as RuleFamily | '',
      ruleTypeRequired: '' as RuleFamily | '',
      outcome: '' as RuleOutcome | '',
      // Tri-state as a string so "Any" can be an option value.
      executed: '' as '' | 'true' | 'false',
      fromDate: '',
      toDate: '',
      loading: false,
      rows: [] as RuleExecutionLog[],
      page: 1,
      pageSize: 25,
      total: 0,
      detailOpen: false,
      detailRow: null as RuleExecutionLog | null,
    };
  },
  computed: {
    modeOptions(): { label: string; value: SelectorMode }[] {
      return [
        { label: this.$t('rule_key_label', 'Rule key'), value: 'rule_key' },
        { label: this.$t('rule_id_label', 'Rule ID'), value: 'rule_id' },
        { label: this.$t('document', 'Document'), value: 'doc_id' },
      ];
    },
    // An example of the identifier the active mode expects, so the field says
    // what shape of value belongs in it.
    selectorPlaceholder(): string {
      if (this.mode === 'rule_id') {
        return '0199c4d1-3a2e-7b41-9f02-5c7e10a4b8d3';
      }
      return this.mode === 'doc_id' ? 'INV-2026-004192' : 'vat_id_required';
    },
    // doc_id mode takes its family from the required select beside the input;
    // the other modes take it from the filter grid.
    activeRuleType(): RuleFamily | '' {
      return this.mode === 'doc_id' ? this.ruleTypeRequired : this.ruleType;
    },
    selectorMissing(): boolean {
      return !this.selector.trim();
    },
    ruleTypeMissing(): boolean {
      return this.mode === 'doc_id' && !this.ruleTypeRequired;
    },
    // The endpoint's contract, mirrored so an invalid query is answered here
    // instead of spending a round trip to be told the same thing.
    queryError(): QueryError | null {
      if (this.selectorMissing) {
        return {
          code: 400,
          message: this.$t(
            'rule_log_selector_required',
            'At least one of rule_id, rule_key or doc_id is required',
          ),
          hint: this.$t(
            'rule_log_selector_required_hint',
            'Pick a selector above. The table takes one row per evaluation per document, so there is no org-wide listing to page through.',
          ),
        };
      }
      if (this.ruleTypeMissing) {
        return {
          code: 400,
          message: this.$t(
            'rule_log_rule_type_required',
            'rule_type is required when filtering by doc_id — one of validation, transformation, layout_selection',
          ),
          hint: this.$t(
            'rule_log_rule_type_required_hint',
            "A document's run leaves entries from all three rule families behind, so the query has to say which kind you want.",
          ),
        };
      }
      if (this.fromDate && this.toDate && this.fromDate > this.toDate) {
        return {
          code: 400,
          message: this.$t(
            'rule_log_date_range_invalid',
            'from_date must not be after to_date',
          ),
          hint: this.$t('rule_log_date_range_hint', 'Swap the two dates.'),
        };
      }
      return null;
    },
    ruleTypeRequiredOptions(): { label: string; value: RuleFamily | '' }[] {
      return [
        { label: this.$t('choose_one', 'Choose one…'), value: '' },
        ...this.ruleTypeOptions,
      ];
    },
    ruleTypeOptions(): { label: string; value: RuleFamily }[] {
      return [
        { label: this.$t('rule_type_validation'), value: 'validation' },
        { label: this.$t('rule_type_transformation'), value: 'transformation' },
        {
          label: this.$t('rule_type_layout_selection'),
          value: 'layout_selection',
        },
      ];
    },
    ruleTypeFilterOptions(): { label: string; value: RuleFamily | '' }[] {
      return [{ label: this.$t('all'), value: '' }, ...this.ruleTypeOptions];
    },
    outcomeOptions(): { label: string; value: RuleOutcome | '' }[] {
      return [
        { label: this.$t('all'), value: '' },
        ...OUTCOMES.map((value) => ({
          label: this.outcomeLabel(value),
          value,
        })),
      ];
    },
    executedOptions(): { label: string; value: '' | 'true' | 'false' }[] {
      return [
        { label: this.$t('all'), value: '' },
        { label: this.$t('executed_true'), value: 'true' },
        { label: this.$t('executed_false'), value: 'false' },
      ];
    },
    columns(): UnifiedTableColumn[] {
      return [
        {
          name: 'created_on',
          label: this.$t('executed_at'),
          field: 'created_on',
          align: 'left',
        },
        {
          name: 'outcome',
          label: this.$t('outcome'),
          field: 'outcome',
          align: 'left',
        },
        {
          name: 'rule_key',
          label: this.$t('log_rule'),
          field: 'rule_key',
          align: 'left',
        },
        {
          name: 'scope',
          label: this.$t('scope'),
          field: 'scope',
          align: 'left',
        },
        {
          name: 'doc_id',
          label: this.$t('document_id'),
          field: 'doc_id',
          align: 'left',
        },
        {
          name: 'row_index',
          label: this.$t('log_row'),
          field: 'row_index',
          align: 'left',
        },
        {
          name: 'severity',
          label: this.$t('severity'),
          field: 'severity',
          align: 'left',
        },
      ];
    },
    paginationState(): dynamicObj {
      return {
        sortBy: null,
        descending: true,
        page: this.page,
        rowsPerPage: this.pageSize,
        rowsNumber: this.total,
      };
    },
    // Flat key/value view of the selected entry, in the order the API returns
    // the fields. Keys stay the API's own names — this is an audit view.
    detailFields(): { key: string; value: string }[] {
      const row = this.detailRow;
      if (!row) {
        return [];
      }
      const dash = (value: unknown) =>
        value === null || value === undefined || value === ''
          ? '—'
          : String(value);
      return [
        { key: 'outcome', value: this.outcomeLabel(row.outcome) },
        { key: 'executed', value: String(row.executed) },
        { key: 'rule_type', value: this.ruleTypeLabel(row.rule_type) },
        { key: 'rule_key', value: dash(row.rule_key) },
        { key: 'rule_id', value: dash(row.rule_id) },
        { key: 'doc_id', value: dash(row.doc_id) },
        { key: 'doc_type', value: dash(row.doc_type) },
        { key: 'scope', value: dash(row.scope) },
        { key: 'target_field', value: dash(row.target_field) },
        {
          key: 'row_index',
          value: row.row_index === null ? '—' : String(row.row_index),
        },
        {
          key: 'severity',
          value: row.severity ? this.severityLabel(row.severity) : '—',
        },
        {
          key: 'created_on',
          value: this.formatTimestamp(row.created_on) || '—',
        },
        // No actor means the engine ran it, not a person.
        {
          key: 'created_by',
          value:
            row.created_by === null
              ? this.$t('engine_run_no_user')
              : dash(row.created_by_name || row.created_by),
        },
      ];
    },
    // The active query as URL tokens, so the param keys can be tinted without
    // v-html. Built from the same baseQuery() the request uses, plus the paging
    // the table adds, so the strip cannot drift from what was actually sent.
    requestTokens(): { text: string; key: boolean }[] {
      const query: dynamicObj = {
        ...this.baseQuery(),
        skip: (this.page - 1) * this.pageSize,
        limit: this.pageSize,
      };
      const tokens = [{ text: '/rule-execution-logs', key: false }];
      Object.entries(query)
        .filter(
          ([, value]) => value !== undefined && value !== null && value !== '',
        )
        .forEach(([name, value], index) => {
          tokens.push({ text: index === 0 ? '?' : '&', key: false });
          tokens.push({ text: name, key: true });
          tokens.push({ text: `=${value}`, key: false });
        });
      return tokens;
    },
    detailsJson(): string {
      const details = this.detailRow ? this.detailRow.details : null;
      if (details === null || details === undefined) {
        return '—';
      }
      return JSON.stringify(details, null, 2);
    },
  },
  watch: {
    // Switching the parameter invalidates the value typed for the previous one.
    mode() {
      this.selector = '';
      this.runQuery();
    },
    selector() {
      this.runQuery();
    },
    ruleType() {
      this.runQuery();
    },
    ruleTypeRequired() {
      this.runQuery();
    },
    outcome() {
      this.runQuery();
    },
    executed() {
      this.runQuery();
    },
    fromDate() {
      this.runQuery();
    },
    toDate() {
      this.runQuery();
    },
  },
  mounted() {
    this.doc_type_key = String(this.$route.params.doc_type || '');
    this.runQuery();
  },
  methods: {
    formatTimestamp(value: string | null): string {
      return useFormattedTimestamp(value);
    },
    outcomeLabel(outcome: string): string {
      const key = `outcome_${outcome}`;
      const label = this.$t(key);
      // An outcome this build doesn't know yet has no key — show it verbatim
      // rather than the raw translation key.
      return label === key ? outcome : label;
    },
    ruleTypeLabel(ruleType: string): string {
      const key = `rule_type_${ruleType}`;
      const label = this.$t(key);
      return label === key ? ruleType : label;
    },
    severityLabel(severity: string): string {
      const label = this.$t(severity);
      return label === severity ? severity : label;
    },
    outcomeClass(outcome: string): string {
      if (outcome === 'failed') {
        return 'rel-pill--fail';
      }
      if (
        outcome === 'passed' ||
        outcome === 'applied' ||
        outcome === 'matched'
      ) {
        return 'rel-pill--pass';
      }
      return 'rel-pill--idle';
    },
    severityClass(severity: string): string {
      return severity === 'error'
        ? 'rel-severity--error'
        : 'rel-severity--warning';
    },
    // "header · vat_id" — either half can be missing.
    scopeLabel(row: RuleExecutionLog): string {
      return [row.scope, row.target_field].filter(Boolean).join(' · ') || '—';
    },
    // Every filter that is filled in, without paging. An unset one is simply
    // left out, which widens the query rather than breaking it. from/to come
    // from date inputs, so widen them to cover the whole day at both ends.
    baseQuery(): RuleExecutionLogQuery {
      const query: RuleExecutionLogQuery = {};
      if (this.selector.trim()) {
        query[this.mode] = this.selector.trim();
      }
      if (this.activeRuleType) {
        query.rule_type = this.activeRuleType;
      }
      // The route scopes this page to one document type; without it the trail
      // would silently span every doc type in the org.
      if (this.doc_type_key) {
        query.doc_type = this.doc_type_key;
      }
      if (this.outcome) {
        query.outcome = this.outcome;
      }
      if (this.executed) {
        query.executed = this.executed === 'true';
      }
      if (this.fromDate) {
        query.from_date = `${this.fromDate}T00:00:00Z`;
      }
      if (this.toDate) {
        query.to_date = `${this.toDate}T23:59:59Z`;
      }
      return query;
    },
    async runQuery(keepPage = false) {
      if (!keepPage) {
        this.page = 1;
      }
      // A query the endpoint would answer with a 400 is not sent; the notice
      // above the table carries the same status instead.
      if (this.queryError) {
        this.rows = [];
        this.total = 0;
        return;
      }
      const base = this.baseQuery();
      try {
        this.loading = true;
        // One request per view of the table: the response carries both the page
        // and the unpaged `total` for the same filters.
        const page = await ruleExecutionLogsApiService.list({
          ...base,
          skip: (this.page - 1) * this.pageSize,
          limit: this.pageSize,
        });
        this.rows = Array.isArray(page.data) ? page.data : [];
        this.total = page.total ?? 0;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.rows = [];
        this.total = 0;
      } finally {
        this.loading = false;
      }
    },
    async handlePaginationChange(payload: PaginationChangePayload) {
      this.page = payload.page;
      this.pageSize = payload.rowsPerPage;
      await this.runQuery(true);
    },
    openDetail(payload: { row: RuleExecutionLog }) {
      this.detailRow = payload.row;
      this.detailOpen = true;
    },
  },
});
</script>

<style scoped lang="scss">
.rule-execution-logs-page {
  // The request strip is flush against the card's bottom edge, so the card has
  // to clip it rather than let it overhang the rounded corners.
  .rel-query {
    overflow: hidden;
  }

  // Quasar's own `.flex` is `display:flex; flex-wrap:wrap`, so pairing it with
  // Tailwind's `flex-col` in the template yields a column-WRAP container. That
  // caps each flex line's cross size, which squeezed the selector row onto two
  // lines and stretched the filter grid to ~4x its content height. The stack is
